def load_prompts() -> dict:
    """Завантажує промпти з prompts.json."""
    try:
        with open(_PROMPTS_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {"styles": {}}


def save_prompts(data: dict) -> bool:
    """Зберігає промпти в prompts.json."""
    try:
        with open(_PROMPTS_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        return True
    except Exception:
        return False


def get_style_prompt(style: str, variant_index: int = -1) -> str:
    """Повертає промпт для стилю. variant_index=-1 = випадковий."""
    import random
    data = load_prompts()
    styles = data.get("styles", {})
    style_data = styles.get(style)
    if style_data:
        variants = style_data.get("variants", [])
        if variants:
            if variant_index >= 0 and variant_index < len(variants):
                return variants[variant_index]["prompt"]
            return random.choice(variants)["prompt"]
    return _FALLBACK_PROMPTS.get(style, _FALLBACK_PROMPTS["Самурай"])


