def _find_claude_cli() -> str:
    """Find Claude CLI binary."""
    import glob as _glob
    import shutil as _shutil
    # 1. Bundled у папці python/ поруч з generate.py
    local_exe = os.path.join(os.path.dirname(os.path.abspath(__file__)), "claude.exe")
    if os.path.isfile(local_exe):
        return local_exe
    # 2. PATH (npm global install, etc.)
    for name in ("claude.cmd", "claude.exe", "claude"):
        found = _shutil.which(name)
        if found:
            return found
    # 3. Direct known path
    known = os.path.expanduser(r"~\AppData\Roaming\Claude\claude-code")
    if os.path.isdir(known):
        for d in sorted(os.listdir(known), reverse=True):
            exe = os.path.join(known, d, "claude.exe")
            if os.path.isfile(exe):
                return exe
    # 4. Glob fallback
    for pattern in [
        os.path.expanduser("~/AppData/Roaming/Claude/claude-code/*/claude.exe"),
        os.path.expanduser("~/AppData/Local/Programs/claude/claude.exe"),
    ]:
        matches = sorted(_glob.glob(pattern), reverse=True)
        if matches:
            return matches[0]
    return ""


def _assemble_image_prompt(img: dict) -> str:
    """Повертає image_prompt як JSON string для Nano Banana Pro формату.

    Якщо промпт вже у Nano Banana Pro форматі (має поля Style, Subject, MadeOutOf тощо),
    повертає JSON as-is. Інакше збирає з legacy полів.
    """
    # Nano Banana Pro format — повертаємо JSON as-is
    if img.get("Style") or img.get("Subject") or img.get("MadeOutOf"):
        return json.dumps(img, ensure_ascii=False, indent=2)

    # Legacy format — збираємо текст для сумісності
    parts = []
    angle = img.get("angle", "")
    if angle:
        parts.append(f"FRAMING: {angle}.")
    if img.get("camera"):
        parts.append(img["camera"] + ".")
    if img.get("persona"):
        parts.append(f"Subject: fictional {img['persona']} warrior character.")
    if img.get("character_description"):
        parts.append(img["character_description"])
    if img.get("location"):
        parts.append(img["location"] + ".")
    if img.get("weather"):
        parts.append(img["weather"] + ".")
    if img.get("scene_description"):
        parts.append(img["scene_description"])
    return " ".join(parts) if parts else ""


def _assemble_video_prompt(vid: dict) -> str:
    """Збирає video_prompt JSON полів в один текстовий промпт."""
    # scene_description вже містить повний промпт
    if vid.get("scene_description"):
        return vid["scene_description"]
    parts = []
    parts.append("Cinematic slow motion. A continuous single unbroken shot.")
    if vid.get("lighting"):
        parts.append(vid["lighting"] + ".")
    if vid.get("camera_movement"):
        parts.append(vid["camera_movement"] + ".")
    if vid.get("weather_description"):
        parts.append(vid["weather_description"] + ".")
    if vid.get("character_behavior"):
        parts.append(vid["character_behavior"] + ".")
    parts.append("Everything moves at half speed, smooth and fluid. No flashes no explosions no bright light no fire no god rays at any point. The lighting stays exactly the same from first frame to last frame.")
    return " ".join(parts)


def _parse_claude_response(text: str, style: str) -> str | None:
    """Parse Claude response — handles both new JSON structure and legacy flat format."""
    global _last_claude_video_prompt
    try:
        import re
        m = re.search(r'\{.*\}', text, re.DOTALL)
        if m:
            data = json.loads(m.group())
            img = data.get("image_prompt", "")
            vid = data.get("video_prompt", "")

            # New structured format: image_prompt is a dict with fields
            if isinstance(img, dict):
                _last_claude_video_prompt = _assemble_video_prompt(vid) if isinstance(vid, dict) else str(vid)
                return _assemble_image_prompt(img)
            # Legacy flat format: image_prompt is a string
            else:
                _last_claude_video_prompt = _assemble_video_prompt(vid) if isinstance(vid, dict) else str(vid)
                return str(img) if img else text
    except Exception:
        pass
    _last_claude_video_prompt = ""
    return text


# --- Diversity tracking ---
_HISTORY_FILE = os.path.join(OUTPUT_DIR, "_prompt_history.json")
_MAX_HISTORY = 12


def _load_history() -> list[dict]:
    try:
        if os.path.isfile(_HISTORY_FILE):
            with open(_HISTORY_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception:
        pass
    return []


def _save_history(history: list[dict]):
    try:
        os.makedirs(os.path.dirname(_HISTORY_FILE), exist_ok=True)
        with open(_HISTORY_FILE, "w", encoding="utf-8") as f:
            json.dump(history[-_MAX_HISTORY:], f, ensure_ascii=False, indent=2)
    except Exception:
        pass


def _pick_diverse(options: list[str], key: str, history: list[dict]) -> str:
    """Pick a random option avoiding recent history for this key."""
    import random
    recent = [h.get(key) for h in history[-5:]]
    available = [o for o in options if o not in recent]
    if not available:
        available = options
    return random.choice(available)


def generate_prompt_for_style(style: str) -> dict | None:
    """Generate image+video+quote prompts via Claude CLI for the given style.
    Loads master prompt from python/prompts/{style.lower()}_master_prompt.md
    Returns dict with image_prompt, video_prompt, quote — or None on failure.
    """
    prompts_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "prompts")
    master_path = os.path.join(prompts_dir, f"{style.lower()}_master_prompt.md")

    if not os.path.isfile(master_path):
        print(f"[Claude] Master prompt not found: {master_path}", flush=True)
        return None

    with open(master_path, "r", encoding="utf-8") as f:
        master = f.read()

    # Per-style variety options
    _VARIETY = {
        "hokan": {
            "warriors":    ["samurai with oni mask", "ronin with scarred face no mask", "ashigaru foot soldier with banner", "sohei warrior monk with naginata", "shogun warlord mounted on horse", "shinobi assassin crouching at night"],
            "backgrounds": ["dark misty forest", "devastated battlefield", "snowy mountain blizzard", "destroyed temple in rain", "stone torii gate in fog", "wooden bridge over gorge", "dark Japanese garden", "bamboo grove in rain", "burning castle ruins"],
            "angles":      ["close-up from chest up side profile", "extreme close-up of mask only", "full body dramatic low angle", "medium shot from behind", "low angle looking up at mounted warrior"],
        },
        "mushin": {
            "warriors":    ["armored samurai matte black armor oni mask", "armored samurai deep crimson armor kuwagata horns", "unarmored ronin dark robes scarred face", "unarmored ronin wet hair stoic expression", "silhouette warrior kasa hat against sky"],
            "backgrounds": ["dark misty plains bokeh campfire lights", "golden amber wheat field explosive sunset backlight", "heavy rain storm dark storm clouds puddle reflections", "field of deep crimson poppies grey sky", "snowfall white mountain peaks cold palette", "burning battlefield orange fire embers smoke", "explosive gold orange sunset silhouette sky"],
            "angles":      ["extreme close-up oni mask fills entire frame", "medium portrait chest to head low angle", "full body low angle dramatic sky behind", "from behind facing vast landscape", "profile side view strong rim light"],
        },
    }
    style_key = style.lower()
    variety = _VARIETY.get(style_key, _VARIETY["hokan"])

    history = _load_history()
    warriors    = variety["warriors"]
    backgrounds = variety["backgrounds"]
    angles      = variety["angles"]

    w = _pick_diverse(warriors, "warrior", history)
    bg = _pick_diverse(backgrounds, "background", history)
    ang = _pick_diverse(angles, "angle", history)
    history.append({"warrior": w, "background": bg, "angle": ang})
    _save_history(history)

    user_msg = (
        f"Generate one unique scene with these specific choices:\n"
        f"- Warrior: {w}\n- Background: {bg}\n- Camera angle: {ang}\n\n"
        f"Return ONLY the JSON object."
    )
    full_prompt = f"{master}\n\n{user_msg}"

    claude_cli = _find_claude_cli()
    if not claude_cli:
        _diag_log("CLI not found via _find_claude_cli")
        print("[Claude] CLI not found", flush=True)
        return None
    _diag_log(f"CLI path: {claude_cli}")

    try:
        prompt_with_instruction = full_prompt + "\n\nReturn ONLY the JSON object, nothing else."
        print(f"[Claude] Sending via -p flag ({len(prompt_with_instruction)} chars)", flush=True)
        _diag_log(f"subprocess.run start, prompt_len={len(prompt_with_instruction)}, style={style}")

        result = subprocess.run(
            [claude_cli, "-p", prompt_with_instruction, "--output-format", "text"],
            capture_output=True, text=True, encoding='utf-8', timeout=120,
        )

        print(f"[Claude] rc={result.returncode} stdout={result.stdout[:500]!r}", flush=True)
        _diag_log(
            f"subprocess.run done rc={result.returncode} "
            f"stdout_len={len(result.stdout or '')} stderr_len={len(result.stderr or '')}"
        )
        if result.returncode != 0 or not (result.stdout or "").strip():
            _diag_log(f"FAIL stdout[:500]={result.stdout[:500]!r}")
            _diag_log(f"FAIL stderr[:1500]={result.stderr[:1500]!r}")
        if result.returncode == 0 and result.stdout.strip():
            import re
            m = re.search(r'\{.*\}', result.stdout.strip(), re.DOTALL)
            if m:
                try:
                    return json.loads(m.group())
                except Exception as je:
                    _diag_log(f"JSON parse fail: {je}; raw[:500]={m.group()[:500]!r}")
                    print(f"[Claude] JSON parse error: {je}", flush=True)
                    return None
            _diag_log(f"No JSON regex match in stdout[:500]={result.stdout[:500]!r}")
            print(f"[Claude] No JSON found", flush=True)
        else:
            print(f"[Claude] stderr={result.stderr[:300]!r}", flush=True)
    except subprocess.TimeoutExpired as e:
        _diag_log(f"subprocess timeout after {e.timeout}s")
        print(f"[Claude] Timeout: {e}", flush=True)
    except Exception as e:
        _diag_log(f"Exception: {type(e).__name__}: {e}")
        print(f"[Claude] Error: {e}", flush=True)

    return None


def _diag_log(msg: str) -> None:
    """Append diagnostic line to python/prompt_diag.log (для дебагу running backend)."""
    try:
        path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "prompt_diag.log")
        with open(path, "a", encoding="utf-8") as f:
            f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {msg}\n")
    except Exception:
        pass


def _generate_prompt_json_with_gemini_UNUSED(style: str, custom_prompt: str, api_key: str) -> dict | None:
    """Генерує повний JSON промпт через Gemini використовуючи повний master prompt."""
    master = _load_master_prompt()
    master_str = json.dumps(master, ensure_ascii=False) if master else ""

    prompt_text = (
        "You are an expert AI image prompt engineer for mushinjournal samurai Instagram account.\n"
        "Below is the complete master style guide in JSON format.\n"
        "Follow it EXACTLY: use the correct frequency weights for character type, camera angle, and background.\n"
        "Vary the details every generation: armor color, specific weather details, lighting direction, battle damage.\n\n"
        f"MASTER STYLE GUIDE:\n{master_str}\n\n"
    )
    if custom_prompt:
        prompt_text += f"Additional context to incorporate: {custom_prompt}\n\n"
    prompt_text += (
        "Generate ONE unique image prompt following the style guide.\n"
        "Return ONLY a JSON object with these exact fields:\n"
        "{\n"
        '  "id": 1,\n'
        '  "warrior": "samurai | ronin | silhouette",\n'
        '  "shot": "short description of the shot type, e.g. oni mask close-up",\n'
        '  "atmosphere": "weather and atmosphere, e.g. rain + steam",\n'
        '  "palette": "specific color palette, e.g. deep prussian navy, matte obsidian black",\n'
        '  "prompt": "full hyper-detailed prompt in English, 4-6 sentences with all quality tags"\n'
        "}"
    )

    for attempt in range(3):
        try:
            resp = requests.post(
                f"https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key={api_key}",
                headers={"Content-Type": "application/json"},
                json={"contents": [{"parts": [{"text": prompt_text}]}],
                      "generationConfig": {"maxOutputTokens": 2048, "temperature": 1.0,
                                           "response_mime_type": "application/json"}},
                timeout=30,
            )
            if resp.status_code == 200:
                text = resp.json()["candidates"][0]["content"]["parts"][0]["text"].strip()
                # response_mime_type=json повертає чистий JSON без markdown
                try:
                    return json.loads(text)
                except Exception:
                    import re
                    m = re.search(r'\{.*\}', text, re.DOTALL)
                    if m:
                        try:
                            return json.loads(m.group())
                        except Exception:
                            continue
        except Exception:
            continue
    return None


