# ===== IMAGE GENERATION =====

def generate_image(prompt: str, style: str, provider: str, api_key: str, variant_index: int = -1, claude_api_key: str = "", gemini_api_key: str = "") -> dict:
    # If prompt already provided from UI (generated by Claude) — use it directly
    full_prompt = prompt if prompt else _build_image_prompt(style, prompt, variant_index, claude_api_key, gemini_api_key)
    try:
        if provider == "stability":
            return _stability_image(full_prompt, api_key)
        elif provider == "openai":
            return _openai_image(full_prompt, api_key)
        elif provider == "replicate":
            return _replicate_image(full_prompt, api_key)
        elif provider == "google":
            return _google_imagen(full_prompt, api_key)
        else:
            return {"ok": False, "error": f"Невідомий провайдер: {provider}"}
    except Exception as e:
        return {"ok": False, "error": f"{type(e).__name__}: {str(e)}"}


def _stability_image(prompt: str, api_key: str) -> dict:
    """Stability AI — Stable Image Core / SDXL"""
    url = "https://api.stability.ai/v2beta/stable-image/generate/core"
    resp = requests.post(
        url,
        headers={
            "Authorization": f"Bearer {api_key}",
            "Accept": "image/*",
        },
        files={"none": ""},
        data={
            "prompt": prompt,
            "output_format": "png",
            "aspect_ratio": "9:16",
        },
        timeout=60,
    )
    if resp.status_code == 200:
        path = os.path.join(OUTPUT_DIR, f"img_{int(time.time())}.png")
        with open(path, "wb") as f:
            f.write(resp.content)
        return {"ok": True, "path": path}
    else:
        try:
            err = resp.json()
            msg = err.get("message", err.get("name", resp.text[:200]))
        except Exception:
            msg = resp.text[:200]
        return {"ok": False, "error": f"Stability API {resp.status_code}: {msg}"}


def _openai_image(prompt: str, api_key: str) -> dict:
    """OpenAI DALL-E 3"""
    resp = requests.post(
        "https://api.openai.com/v1/images/generations",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        json={
            "model": "dall-e-3",
            "prompt": prompt,
            "n": 1,
            "size": "1024x1792",
            "response_format": "b64_json",
        },
        timeout=60,
    )
    if resp.status_code == 200:
        data = resp.json()
        b64 = data["data"][0]["b64_json"]
        path = os.path.join(OUTPUT_DIR, f"img_{int(time.time())}.png")
        with open(path, "wb") as f:
            f.write(base64.b64decode(b64))
        return {"ok": True, "path": path}
    else:
        try:
            err = resp.json()
            msg = err.get("error", {}).get("message", resp.text[:200])
        except Exception:
            msg = resp.text[:200]
        return {"ok": False, "error": f"OpenAI API {resp.status_code}: {msg}"}


def _replicate_image(prompt: str, api_key: str) -> dict:
    """Replicate — Flux Schnell"""
    # Create prediction
    resp = requests.post(
        "https://api.replicate.com/v1/models/black-forest-labs/flux-schnell/predictions",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        json={
            "input": {
                "prompt": prompt,
                "aspect_ratio": "9:16",
                "output_format": "png",
            }
        },
        timeout=30,
    )
    if resp.status_code not in (200, 201):
        return {"ok": False, "error": f"Replicate API {resp.status_code}: {resp.text[:200]}"}

    prediction = resp.json()
    poll_url = prediction.get("urls", {}).get("get", f"https://api.replicate.com/v1/predictions/{prediction['id']}")

    # Poll for result
    for _ in range(60):
        time.sleep(3)
        poll = requests.get(poll_url, headers={"Authorization": f"Bearer {api_key}"}, timeout=15)
        data = poll.json()
        status = data.get("status")
        if status == "succeeded":
            output = data.get("output")
            image_url = output[0] if isinstance(output, list) else output
            img_resp = requests.get(image_url, timeout=30)
            path = os.path.join(OUTPUT_DIR, f"img_{int(time.time())}.png")
            with open(path, "wb") as f:
                f.write(img_resp.content)
            return {"ok": True, "path": path}
        elif status == "failed":
            return {"ok": False, "error": f"Replicate failed: {data.get('error', 'unknown')}"}

    return {"ok": False, "error": "Replicate timeout"}


def _google_imagen(prompt: str, api_key: str) -> dict:
    """Google Imagen 4 via AI Studio API key"""

    def _try_imagen4(model: str) -> dict | None:
        """Imagen 4 — predict endpoint"""
        url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:predict?key={api_key}"
        resp = requests.post(url, headers={"Content-Type": "application/json"}, json={
            "instances": [{"prompt": prompt}],
            "parameters": {"sampleCount": 1, "aspectRatio": "9:16"},
        }, timeout=120)
        if resp.status_code == 200:
            predictions = resp.json().get("predictions", [])
            if predictions:
                b64 = predictions[0].get("bytesBase64Encoded", "")
                if b64:
                    path = os.path.join(OUTPUT_DIR, f"img_{int(time.time())}.png")
                    with open(path, "wb") as f:
                        f.write(base64.b64decode(b64))
                    return {"ok": True, "path": path}
        return None

    def _try_gemini_image(model: str) -> dict | None:
        """Gemini image models — generateContent endpoint"""
        url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent?key={api_key}"
        resp = requests.post(url, headers={"Content-Type": "application/json"}, json={
            "contents": [{"parts": [{"text": prompt}]}],
            "generationConfig": {"responseModalities": ["IMAGE"]},
        }, timeout=120)
        if resp.status_code == 200:
            try:
                parts = resp.json()["candidates"][0]["content"]["parts"]
                for part in parts:
                    if "inlineData" in part:
                        b64 = part["inlineData"]["data"]
                        path = os.path.join(OUTPUT_DIR, f"img_{int(time.time())}.png")
                        with open(path, "wb") as f:
                            f.write(base64.b64decode(b64))
                        return {"ok": True, "path": path}
            except (KeyError, IndexError):
                pass
        return None

    # Спробуємо моделі по черзі від найкращої
    for attempt in [
        lambda: _try_imagen4("imagen-4.0-generate-001"),
        lambda: _try_gemini_image("gemini-2.5-flash-image"),
        lambda: _try_gemini_image("gemini-3-pro-image-preview"),
        lambda: _try_gemini_image("gemini-3.1-flash-image-preview"),
    ]:
        result = attempt()
        if result:
            return result

    return {"ok": False, "error": "Google Imagen: жодна модель не повернула зображення. Перевірте API ключ."}


