def generate_video(image_path: str, prompt: str, provider: str, api_key: str) -> dict:
    try:
        if provider == "kling":
            return _kling_video(image_path, prompt, api_key)
        elif provider == "runway":
            return _runway_video(image_path, prompt, api_key)
        elif provider == "luma":
            return _luma_video(image_path, prompt, api_key)
        elif provider == "veo":
            return _veo_video(image_path, prompt, api_key)
        elif provider == "nhungoc_veo3":
            return _nhungoc_veo3_video(image_path, prompt, api_key)
        else:
            return {"ok": False, "error": f"Невідомий провайдер відео: {provider}"}
    except Exception as e:
        return {"ok": False, "error": f"{type(e).__name__}: {str(e)}"}


def _image_to_base64(path: str) -> str:
    with open(path, "rb") as f:
        return base64.b64encode(f.read()).decode()


def _kling_jwt(access_key: str, secret_key: str) -> str:
    """Generate JWT token for Kling AI API."""
    import struct

    # Header
    header = base64.urlsafe_b64encode(json.dumps({"alg": "HS256", "typ": "JWT"}).encode()).rstrip(b"=")

    # Payload
    now = int(time.time())
    payload_data = {
        "iss": access_key,
        "exp": now + 1800,
        "nbf": now - 5,
        "iat": now,
    }
    payload = base64.urlsafe_b64encode(json.dumps(payload_data).encode()).rstrip(b"=")

    # Signature
    signing_input = header + b"." + payload
    signature = base64.urlsafe_b64encode(
        hmac.new(secret_key.encode(), signing_input, hashlib.sha256).digest()
    ).rstrip(b"=")

    return (signing_input + b"." + signature).decode()


def _kling_video(image_path: str, prompt: str, api_key: str) -> dict:
    """Kling AI — image-to-video via official API.
    api_key format: 'access_key:secret_key'
    """
    if ":" not in api_key:
        return {"ok": False, "error": "Kling API key має бути у форматі 'access_key:secret_key'"}

    access_key, secret_key = api_key.split(":", 1)
    token = _kling_jwt(access_key, secret_key)

    img_b64 = _image_to_base64(image_path)

    # Create task
    resp = requests.post(
        "https://api.klingai.com/v1/videos/image2video",
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        },
        json={
            "model_name": "kling-v1",
            "mode": "std",
            "duration": "5",
            "image": img_b64,
            "prompt": prompt or "Slow cinematic camera movement, dramatic lighting",
        },
        timeout=30,
    )

    if resp.status_code not in (200, 201):
        return {"ok": False, "error": f"Kling API {resp.status_code}: {resp.text[:300]}"}

    data = resp.json()
    task_id = data.get("data", {}).get("task_id")
    if not task_id:
        return {"ok": False, "error": f"Kling: no task_id in response: {json.dumps(data)[:300]}"}

    # Poll for result
    for _ in range(120):  # ~10 min max
        time.sleep(5)
        token = _kling_jwt(access_key, secret_key)  # refresh token
        poll = requests.get(
            f"https://api.klingai.com/v1/videos/image2video/{task_id}",
            headers={"Authorization": f"Bearer {token}"},
            timeout=15,
        )
        result = poll.json()
        task_status = result.get("data", {}).get("task_status")

        if task_status == "succeed":
            videos = result.get("data", {}).get("task_result", {}).get("videos", [])
            if videos:
                video_url = videos[0].get("url")
                vid_resp = requests.get(video_url, timeout=60)
                path = os.path.join(OUTPUT_DIR, f"vid_{int(time.time())}.mp4")
                with open(path, "wb") as f:
                    f.write(vid_resp.content)
                return {"ok": True, "path": path}
            return {"ok": False, "error": "Kling: відео не знайдено у відповіді"}
        elif task_status == "failed":
            msg = result.get("data", {}).get("task_status_msg", "unknown error")
            return {"ok": False, "error": f"Kling failed: {msg}"}

    return {"ok": False, "error": "Kling timeout (10 хвилин)"}


def _runway_video(image_path: str, prompt: str, api_key: str) -> dict:
    """Runway ML Gen-3 Alpha — image-to-video."""
    img_b64 = _image_to_base64(image_path)

    resp = requests.post(
        "https://api.dev.runwayml.com/v1/image_to_video",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            "X-Runway-Version": "2024-11-06",
        },
        json={
            "model": "gen3a_turbo",
            "promptImage": f"data:image/png;base64,{img_b64}",
            "promptText": prompt or "Slow cinematic camera movement, dramatic lighting",
            "duration": 5,
            "ratio": "768:1344",
        },
        timeout=30,
    )

    if resp.status_code not in (200, 201):
        return {"ok": False, "error": f"Runway API {resp.status_code}: {resp.text[:300]}"}

    task_id = resp.json().get("id")

    # Poll
    for _ in range(120):
        time.sleep(5)
        poll = requests.get(
            f"https://api.dev.runwayml.com/v1/tasks/{task_id}",
            headers={"Authorization": f"Bearer {api_key}"},
            timeout=15,
        )
        result = poll.json()
        status = result.get("status")

        if status == "SUCCEEDED":
            video_url = result.get("output", [None])[0]
            if video_url:
                vid_resp = requests.get(video_url, timeout=60)
                path = os.path.join(OUTPUT_DIR, f"vid_{int(time.time())}.mp4")
                with open(path, "wb") as f:
                    f.write(vid_resp.content)
                return {"ok": True, "path": path}
            return {"ok": False, "error": "Runway: відео не знайдено"}
        elif status == "FAILED":
            return {"ok": False, "error": f"Runway failed: {result.get('failure', 'unknown')}"}

    return {"ok": False, "error": "Runway timeout"}


def _luma_video(image_path: str, prompt: str, api_key: str) -> dict:
    """Luma Dream Machine — image-to-video."""
    img_b64 = _image_to_base64(image_path)

    resp = requests.post(
        "https://api.lumalabs.ai/dream-machine/v1/generations",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        json={
            "prompt": prompt or "Slow cinematic camera movement, dramatic lighting",
            "keyframes": {
                "frame0": {
                    "type": "image",
                    "url": f"data:image/png;base64,{img_b64}",
                }
            },
            "aspect_ratio": "9:16",
        },
        timeout=30,
    )

    if resp.status_code not in (200, 201):
        return {"ok": False, "error": f"Luma API {resp.status_code}: {resp.text[:300]}"}

    gen_id = resp.json().get("id")

    # Poll
    for _ in range(120):
        time.sleep(5)
        poll = requests.get(
            f"https://api.lumalabs.ai/dream-machine/v1/generations/{gen_id}",
            headers={"Authorization": f"Bearer {api_key}"},
            timeout=15,
        )
        result = poll.json()
        state = result.get("state")

        if state == "completed":
            video_url = result.get("assets", {}).get("video")
            if video_url:
                vid_resp = requests.get(video_url, timeout=60)
                path = os.path.join(OUTPUT_DIR, f"vid_{int(time.time())}.mp4")
                with open(path, "wb") as f:
                    f.write(vid_resp.content)
                return {"ok": True, "path": path}
            return {"ok": False, "error": "Luma: відео не знайдено"}
        elif state == "failed":
            return {"ok": False, "error": f"Luma failed: {result.get('failure_reason', 'unknown')}"}

    return {"ok": False, "error": "Luma timeout"}


def _veo_video(image_path: str, prompt: str, api_key: str) -> dict:
    """Google Veo 3 — image-to-video via AI Studio API key."""
    img_b64 = _image_to_base64(image_path)

    # Додаємо дисклеймер щоб уникнути фільтру відомих людей
    disclaimer = "Fictional warrior character. Not based on any real person, living or dead."
    safe_prompt = f"{prompt} {disclaimer}" if prompt else disclaimer

    # Спробуємо Veo 3 (найкраща), якщо 403/404 — fallback на Veo 2
    for model in ["veo-3.0-fast-generate-001", "veo-2.0-generate-001"]:
        url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:predictLongRunning?key={api_key}"
        resp = requests.post(
            url,
            headers={"Content-Type": "application/json"},
            json={
                "instances": [{
                    "prompt": safe_prompt or "Epic cinematic slow motion, dramatic camera push-in. Fictional character, not a real person.",
                    "image": {"bytesBase64Encoded": img_b64, "mimeType": "image/png"},
                }],
                "parameters": {
                    "aspectRatio": "9:16",
                    "durationSeconds": 8,
                    "sampleCount": 1,
                },
            },
            timeout=60,
        )

        if resp.status_code in (403, 404):
            continue  # спробуємо наступну модель

        if resp.status_code != 200:
            try:
                msg = resp.json().get("error", {}).get("message", resp.text[:300])
            except Exception:
                msg = resp.text[:300]
            if "PROMINENT_PEOPLE_FILTER" in msg:
                return {"ok": False, "error": "Veo: промт схожий на реальну відому людину. Перегенеруй промт або зміни опис персонажа."}
            return {"ok": False, "error": f"Veo {resp.status_code}: {msg}"}

        operation_name = resp.json().get("name")
        if not operation_name:
            return {"ok": False, "error": "Veo: не отримано operation name"}

        # Polling long-running operation
        poll_url = f"https://generativelanguage.googleapis.com/v1beta/{operation_name}?key={api_key}"
        for _ in range(120):  # max 10 хвилин
            time.sleep(5)
            poll = requests.get(poll_url, timeout=15)
            if poll.status_code != 200:
                continue
            result = poll.json()
            if not result.get("done"):
                continue

            # Перевіряємо помилку в операції
            if result.get("error"):
                err_msg = result["error"].get("message", str(result["error"]))
                if "PROMINENT_PEOPLE_FILTER" in err_msg:
                    return {"ok": False, "error": "Veo: промт схожий на реальну відому людину. Перегенеруй промт або зміни опис персонажа."}
                return {"ok": False, "error": f"Veo: {err_msg}"}

            # Готово — розбираємо структуру відповіді
            response_data = result.get("response", result)
            # Перевіряємо operations[] на помилки (Veo 3 повертає так)
            ops = response_data.get("operations", [])
            if ops:
                for op in ops:
                    op_err = op.get("error", {})
                    if op_err:
                        op_msg = op_err.get("message", str(op_err))
                        if "PROMINENT_PEOPLE_FILTER" in op_msg:
                            return {"ok": False, "error": "Veo: промт схожий на реальну відому людину. Перегенеруй промт або зміни опис персонажа."}
                        return {"ok": False, "error": f"Veo: {op_msg}"}
            # Veo повертає response.generateVideoResponse
            if "generateVideoResponse" in response_data:
                response_data = response_data["generateVideoResponse"]
            # Спробуємо різні структури відповіді
            try:
                # Варіант 1: response.predictions[0].bytesBase64Encoded
                predictions = response_data.get("predictions", [])
                if predictions:
                    video_b64 = predictions[0].get("bytesBase64Encoded", "")
                    if video_b64:
                        path = os.path.join(OUTPUT_DIR, f"vid_{int(time.time())}.mp4")
                        with open(path, "wb") as f:
                            f.write(base64.b64decode(video_b64))
                        return {"ok": True, "path": path}
                    video_uri = predictions[0].get("videoUri", "")
                    if video_uri:
                        vid_resp = requests.get(video_uri, timeout=60)
                        path = os.path.join(OUTPUT_DIR, f"vid_{int(time.time())}.mp4")
                        with open(path, "wb") as f:
                            f.write(vid_resp.content)
                        return {"ok": True, "path": path}

                # Варіант 2: generatedSamples[0].video
                samples = response_data.get("generatedSamples", [])
                if samples:
                    video_obj = samples[0].get("video", {})
                    video_b64 = video_obj.get("bytesBase64Encoded", "")
                    if video_b64:
                        path = os.path.join(OUTPUT_DIR, f"vid_{int(time.time())}.mp4")
                        with open(path, "wb") as f:
                            f.write(base64.b64decode(video_b64))
                        return {"ok": True, "path": path}
                    video_uri = video_obj.get("uri", video_obj.get("videoUri", ""))
                    if video_uri:
                        # Додаємо API ключ для завантаження з Google Files API
                        sep = "&" if "?" in video_uri else "?"
                        download_url = f"{video_uri}{sep}key={api_key}"
                        vid_resp = requests.get(download_url, timeout=120)
                        path = os.path.join(OUTPUT_DIR, f"vid_{int(time.time())}.mp4")
                        with open(path, "wb") as f:
                            f.write(vid_resp.content)
                        return {"ok": True, "path": path}

                # Нічого не знайдено — повертаємо структуру для діагностики
                keys = list(response_data.keys())
                return {"ok": False, "error": f"Veo: невідома структура відповіді. Ключі: {keys}"}

            except Exception as e:
                return {"ok": False, "error": f"Veo: {e}. Response keys: {list(response_data.keys())}"}

        return {"ok": False, "error": "Veo timeout (10 хвилин)"}

    return {"ok": False, "error": "Veo: немає доступних моделей для цього API ключа"}


# ===== FFMPEG COMPOSE =====

def _find_font() -> str:
    """Find a usable font file on Windows."""
    candidates = [
        r"C:\Windows\Fonts\arial.ttf",
        r"C:\Windows\Fonts\Arial.ttf",
        r"C:\Windows\Fonts\calibri.ttf",
        r"C:\Windows\Fonts\segoeui.ttf",
        r"C:\Windows\Fonts\tahoma.ttf",
        r"C:\Windows\Fonts\verdana.ttf",
    ]
    for p in candidates:
        if os.path.isfile(p):
            return p.replace("\\", "/")
    return ""


def _find_cjk_font() -> str:
    """Find a font that supports CJK (kanji) characters."""
    candidates = [
        r"C:\Windows\Fonts\YuGothL.ttc",
        r"C:\Windows\Fonts\YuGothR.ttc",
        r"C:\Windows\Fonts\YuGothM.ttc",
        r"C:\Windows\Fonts\msgothic.ttc",
        r"C:\Windows\Fonts\RODE Noto Sans CJK SC R.otf",
        r"C:\Windows\Fonts\meiryo.ttc",
        r"C:\Windows\Fonts\malgun.ttf",
    ]
    for p in candidates:
        if os.path.isfile(p):
            return p.replace("\\", "/")
    return _find_font()


def _find_ffmpeg() -> str:
    """Find ffmpeg binary."""
    for cmd in ["ffmpeg", "ffmpeg.exe"]:
        try:
            subprocess.run([cmd, "-version"], capture_output=True, timeout=5)
            return cmd
        except Exception:
            continue
    # Common Windows paths
    for p in [
        os.path.expanduser(r"~\AppData\Local\Microsoft\WinGet\Links\ffmpeg.exe"),
        os.path.expanduser(r"~\AppData\Local\Microsoft\WinGet\Packages\Gyan.FFmpeg_Microsoft.Winget.Source_8wekyb3d8bbwe\ffmpeg-7.1-full_build\bin\ffmpeg.exe"),
        r"C:\ProgramData\chocolatey\bin\ffmpeg.exe",
        r"C:\Program Files\FFmpeg\bin\ffmpeg.exe",
        r"C:\ffmpeg\bin\ffmpeg.exe",
        os.path.expanduser(r"~\scoop\shims\ffmpeg.exe"),
    ]:
        if os.path.isfile(p):
            return p
    return "ffmpeg"


def _get_video_duration(video_path: str) -> float:
    """Повертає тривалість відео у секундах через ffprobe. 0.0 якщо не вдалось."""
    if not video_path or not os.path.isfile(video_path):
        return 0.0
    ffmpeg = _find_ffmpeg()
    # ffprobe зазвичай поряд з ffmpeg
    ffprobe = ffmpeg.replace("ffmpeg.exe", "ffprobe.exe").replace("ffmpeg", "ffprobe")
    if ffprobe == ffmpeg:
        ffprobe = "ffprobe"
    try:
        result = subprocess.run(
            [ffprobe, "-v", "error", "-show_entries", "format=duration",
             "-of", "default=noprint_wrappers=1:nokey=1", video_path],
            capture_output=True, text=True, timeout=10,
        )
        if result.returncode == 0 and result.stdout.strip():
            return float(result.stdout.strip())
    except Exception:
        pass
    return 0.0


# ===== HARDWARE ACCELERATION DETECTION =====

_HW_ENCODER_CACHE = None

def _detect_hw_encoder() -> str:
    """Визначає найкращий доступний hardware encoder.

    Returns: 'qsv' | 'nvenc' | 'amf' | 'cpu'
    Кеш — детект робиться 1 раз.
    """
    global _HW_ENCODER_CACHE
    if _HW_ENCODER_CACHE is not None:
        return _HW_ENCODER_CACHE

    ffmpeg = _find_ffmpeg()
    # Тест 1: Intel QSV
    try:
        r = subprocess.run([
            ffmpeg, "-y", "-f", "lavfi", "-i", "testsrc=duration=0.2:size=320x240:rate=10",
            "-c:v", "h264_qsv", "-f", "null", "-",
        ], capture_output=True, text=True, timeout=10)
        if r.returncode == 0:
            _HW_ENCODER_CACHE = "qsv"
            print("[HW] Using Intel QSV encoder", flush=True)
            return "qsv"
    except Exception:
        pass

    # Тест 2: NVIDIA NVENC
    try:
        r = subprocess.run([
            ffmpeg, "-y", "-f", "lavfi", "-i", "testsrc=duration=0.2:size=320x240:rate=10",
            "-c:v", "h264_nvenc", "-f", "null", "-",
        ], capture_output=True, text=True, timeout=10)
        if r.returncode == 0:
            _HW_ENCODER_CACHE = "nvenc"
            print("[HW] Using NVIDIA NVENC encoder", flush=True)
            return "nvenc"
    except Exception:
        pass

    # Тест 3: AMD AMF
    try:
        r = subprocess.run([
            ffmpeg, "-y", "-f", "lavfi", "-i", "testsrc=duration=0.2:size=320x240:rate=10",
            "-c:v", "h264_amf", "-f", "null", "-",
        ], capture_output=True, text=True, timeout=10)
        if r.returncode == 0:
            _HW_ENCODER_CACHE = "amf"
            print("[HW] Using AMD AMF encoder", flush=True)
            return "amf"
    except Exception:
        pass

    _HW_ENCODER_CACHE = "cpu"
    print("[HW] No HW encoder detected, using libx264 CPU", flush=True)
    return "cpu"


def _video_encoder_args(crf: int = 20) -> list:
    """Повертає ffmpeg args для кодування відео — HW якщо є, інакше CPU.

    crf: quality 0-51 (18-23 типово). Для HW енкодерів мапиться на bitrate/qp.
    """
    enc = _detect_hw_encoder()
    if enc == "qsv":
        # Intel Quick Sync — preset veryfast, global_quality мапиться з CRF
        return ["-c:v", "h264_qsv", "-preset", "veryfast", "-global_quality", str(crf)]
    if enc == "nvenc":
        # NVIDIA NVENC — preset p4 (balanced), CQ mode
        return ["-c:v", "h264_nvenc", "-preset", "p4", "-cq", str(crf)]
    if enc == "amf":
        return ["-c:v", "h264_amf", "-quality", "speed", "-rc", "cqp", "-qp_i", str(crf), "-qp_p", str(crf)]
    # CPU fallback — ultrafast замість fast (сильно швидше, трохи більший файл)
    return ["-c:v", "libx264", "-crf", str(crf), "-preset", "ultrafast"]


def _subprocess_low_priority_flags() -> dict:
    """Returns kwargs для subprocess.run щоб запустити з низьким пріоритетом (Windows).

    Щоб не палити ноут навіть на CPU режимі.
    """
    import sys as _sys
    if _sys.platform == "win32":
        # 0x00004000 = BELOW_NORMAL_PRIORITY_CLASS
        return {"creationflags": 0x00004000}
    return {}


def _remove_veo_watermark(video_path: str) -> str:
    """Remove Veo watermark using OpenCV inpaint on each frame.
    Detects bright 'Veo' text in bottom-right corner and fills with surrounding texture."""
    try:
        import cv2
        import numpy as np
    except ImportError:
        # Fallback to crop if OpenCV not available
        return _remove_veo_watermark_crop(video_path)

    ffmpeg = _find_ffmpeg()
    clean_path = video_path.replace(".mp4", "_clean.mp4")

    try:
        # Extract frames
        cap = cv2.VideoCapture(video_path)
        if not cap.isOpened():
            return video_path

        fps = cap.get(cv2.CAP_PROP_FPS) or 24
        w = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        h = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))

        fourcc = cv2.VideoWriter_fourcc(*'mp4v')
        temp_raw = video_path.replace(".mp4", "_raw.mp4")
        writer = cv2.VideoWriter(temp_raw, fourcc, fps, (w, h))

        # Fixed mask for Veo watermark: bottom-right corner, ~155x85px
        watermark_mask = np.zeros((h, w), dtype=np.uint8)
        watermark_mask[h-85:h, w-155:w] = 255

        frame_count = 0
        while True:
            ret, frame = cap.read()
            if not ret:
                break

            clean_frame = cv2.inpaint(frame, watermark_mask, 12, cv2.INPAINT_TELEA)
            writer.write(clean_frame)
            frame_count += 1

        cap.release()
        writer.release()

        if frame_count == 0:
            return video_path

        # Mux with original audio using ffmpeg
        result = subprocess.run([
            ffmpeg, "-y",
            "-i", temp_raw,
            "-i", video_path,
            "-map", "0:v", "-map", "1:a?",
        ] + _video_encoder_args(crf=20) + [
            "-c:a", "copy",
            "-shortest",
            clean_path,
        ], capture_output=True, text=True, timeout=120, **_subprocess_low_priority_flags())

        try:
            os.remove(temp_raw)
        except:
            pass

        if os.path.isfile(clean_path) and os.path.getsize(clean_path) > 1000:
            os.remove(video_path)
            os.rename(clean_path, video_path)
            return video_path

    except Exception:
        pass

    return video_path


def _find_rife() -> str:
    """Знаходить rife-ncnn-vulkan.exe (AI frame interpolation для CapCut-якості slow mo)."""
    local = os.path.join(
        os.path.dirname(os.path.abspath(__file__)),
        "tools", "rife-ncnn-vulkan-20221029-windows", "rife-ncnn-vulkan.exe",
    )
    if os.path.isfile(local):
        return local
    return ""


def _apply_slow_motion_rife(video_path: str, factor: float = 0.7, model: str = "rife-v4.6") -> str:
    """AI-інтерпольоване заповільнення через RIFE (якість як у CapCut).

    Працює через Vulkan (Intel Xe або NVIDIA). Повільніше за blend, але якість суттєво краща.
    """
    rife = _find_rife()
    if not rife:
        print("[rife] не знайдено, fallback на blend", flush=True)
        return _apply_slow_motion_blend(video_path, factor)

    ffmpeg = _find_ffmpeg()
    rife_dir = os.path.dirname(rife)
    model_path = os.path.join(rife_dir, model)
    if not os.path.isdir(model_path):
        print(f"[rife] model {model} not found, using rife-v4.6", flush=True)
        model_path = os.path.join(rife_dir, "rife-v4.6")

    import tempfile as _tmp
    import shutil as _sh
    work = _tmp.mkdtemp(prefix="rife_")
    frames_in = os.path.join(work, "in")
    frames_out = os.path.join(work, "out")
    os.makedirs(frames_in)
    os.makedirs(frames_out)
    slow_path = video_path.replace(".mp4", "_rife.mp4")

    try:
        # 1. Витягуємо кадри з вхідного відео
        subprocess.run([
            ffmpeg, "-y", "-i", video_path,
            "-qscale:v", "2",  # висока якість PNG
            os.path.join(frames_in, "%08d.png"),
        ], capture_output=True, text=True, timeout=180, **_subprocess_low_priority_flags())

        frame_count = len([f for f in os.listdir(frames_in) if f.endswith(".png")])
        if frame_count < 2:
            print("[rife] недостатньо кадрів", flush=True)
            return video_path

        # 2. RIFE інтерполяція — target кількість кадрів = frame_count / factor
        # factor=0.7 → target = 1.43 * frame_count
        target_frames = int(round(frame_count / factor))
        print(f"[rife] {frame_count} → {target_frames} кадрів (factor={factor})", flush=True)

        result = subprocess.run([
            rife, "-i", frames_in, "-o", frames_out,
            "-m", model_path,
            "-n", str(target_frames),
            "-g", "0",  # auto-select GPU (0 = перший Vulkan пристрій)
            "-j", "1:2:2",
        ], capture_output=True, text=True, timeout=900, **_subprocess_low_priority_flags())

        if result.returncode != 0:
            print(f"[rife] rc={result.returncode}: {(result.stderr or '')[-400:]}", flush=True)
            return _apply_slow_motion_blend(video_path, factor)

        out_count = len([f for f in os.listdir(frames_out) if f.endswith(".png")])
        if out_count < frame_count:
            print(f"[rife] мало вихідних кадрів: {out_count}", flush=True)
            return _apply_slow_motion_blend(video_path, factor)

        # 3. Збираємо відео назад з QSV encoder
        encode_cmd = [
            ffmpeg, "-y",
            "-framerate", "24",
            "-i", os.path.join(frames_out, "%08d.png"),
            "-an",
        ] + _video_encoder_args(crf=20) + [slow_path]
        result = subprocess.run(encode_cmd, capture_output=True, text=True, timeout=300,
                                **_subprocess_low_priority_flags())
        if result.returncode != 0:
            print(f"[rife encode] rc={result.returncode}: {(result.stderr or '')[-300:]}", flush=True)
            return _apply_slow_motion_blend(video_path, factor)

        if not (os.path.isfile(slow_path) and os.path.getsize(slow_path) > 1000):
            return _apply_slow_motion_blend(video_path, factor)
    except Exception as e:
        print(f"[rife] exception: {e}", flush=True)
        return _apply_slow_motion_blend(video_path, factor)
    finally:
        try:
            _sh.rmtree(work, ignore_errors=True)
        except Exception:
            pass
    # Повертаємо НОВИЙ шлях — оригінал НЕ чіпаємо (щоб History не перезаписалась).
    return slow_path


def _apply_slow_motion_blend(video_path: str, factor: float = 0.7) -> str:
    """Швидке заповільнення через minterpolate blend (CPU-light, помітний blur).

    Легкий режим (швидкий, не вішає ноут):
      - minterpolate blend mode замість mci (5-10x швидше, без motion estimation)
      - fps=48 замість 96 (вдвічі менше інтерпольованих кадрів)
      - QSV/NVENC encoder якщо є
      - Low process priority
    """
    ffmpeg = _find_ffmpeg()
    slow_path = video_path.replace(".mp4", "_slow.mp4")
    pts_mult = round(1.0 / factor, 4)

    cmd = [
        ffmpeg, "-y", "-i", video_path,
        "-filter_complex",
        # blend mode — просто усереднює сусідні кадри (швидко)
        # fps=48 — удвічі менше інтерпольованих кадрів ніж 96
        f"minterpolate=fps=48:mi_mode=blend,setpts={pts_mult}*PTS,fps=24",
        "-an",
    ] + _video_encoder_args(crf=20) + [slow_path]

    try:
        result = subprocess.run(
            cmd, capture_output=True, text=True, timeout=600,
            **_subprocess_low_priority_flags(),
        )
        if result.returncode != 0:
            print(f"[slow_motion] ffmpeg rc={result.returncode}: {(result.stderr or '')[-400:]}", flush=True)
        # Повертаємо новий шлях щоб НЕ чіпати оригінал
        if os.path.isfile(slow_path) and os.path.getsize(slow_path) > 1000:
            return slow_path
    except Exception as e:
        print(f"[slow_motion] error: {e}", flush=True)
    # Fallback — повертаємо оригінал якщо slow не вдався
    return video_path


def _apply_slow_motion(video_path: str, factor: float = 0.7, mode: str = "blend") -> str:
    """Dispatcher для slow motion.

    mode:
      - 'blend' — швидкий (minterpolate blend), ~20с на 11с відео
      - 'rife'  — AI якість (CapCut-рівень), ~60-120с на 11с відео
      - 'mci'   — motion-compensated (старий), ~60с на 11с відео, 100% CPU
    """
    if mode == "rife":
        return _apply_slow_motion_rife(video_path, factor)
    if mode == "mci":
        return _apply_slow_motion_mci(video_path, factor)
    return _apply_slow_motion_blend(video_path, factor)


def _apply_slow_motion_mci(video_path: str, factor: float = 0.7) -> str:
    """Старий метод — minterpolate mci (motion-compensated). Дуже важкий CPU, якісно."""
    ffmpeg = _find_ffmpeg()
    slow_path = video_path.replace(".mp4", "_mci.mp4")
    pts_mult = round(1.0 / factor, 4)
    cmd = [
        ffmpeg, "-y", "-i", video_path,
        "-filter_complex",
        f"minterpolate=fps=96:mi_mode=mci:mc_mode=aobmc:me_mode=bidir:vsbmc=1,setpts={pts_mult}*PTS,fps=24",
        "-an",
    ] + _video_encoder_args(crf=18) + [slow_path]
    try:
        subprocess.run(cmd, capture_output=True, text=True, timeout=900,
                       **_subprocess_low_priority_flags())
        # Повертаємо новий шлях — оригінал НЕ чіпаємо
        if os.path.isfile(slow_path) and os.path.getsize(slow_path) > 1000:
            return slow_path
    except Exception as e:
        print(f"[slow_motion_mci] error: {e}", flush=True)
    return video_path


def _remove_veo_watermark_crop(video_path: str) -> str:
    """Fallback: remove watermark by cropping bottom-right corner."""
    ffmpeg = _find_ffmpeg()
    clean_path = video_path.replace(".mp4", "_clean.mp4")
    try:
        subprocess.run([
            ffmpeg, "-y", "-i", video_path,
            "-vf", "crop=iw-20:ih-50:0:0,scale=iw+20:ih+50:flags=lanczos",
        ] + _video_encoder_args(crf=20) + [
            "-c:a", "copy",
            clean_path,
        ], capture_output=True, text=True, timeout=120)
        if os.path.isfile(clean_path) and os.path.getsize(clean_path) > 1000:
            os.remove(video_path)
            os.rename(clean_path, video_path)
    except Exception:
        pass
    return video_path


def _nhungoc_veo3_video(image_path: str, prompt: str, api_key: str) -> dict:
    """Generate video via Nhungoc VEO3 WebSocket service.
    Supports both i2v (image-to-video) and t2v (text-to-video).
    Uses i2v when image_path is provided, t2v otherwise.
    """
    import asyncio
    import ssl

    try:
        import websockets
    except ImportError:
        os.system("pip install websockets")
        import websockets

    NHUNGOC_LICENSE = "ELV-333fe11d-1dca8282-6485acf0"
    # Hardware fingerprint цього PC — license прив'язана до нього.
    # Сервер тепер вимагає cpu_id у register payload (повертає "Missing cpu_id" без нього).
    NHUNGOC_CPU_ID = "b014b7d94b33ea5181da4e54ca40730d"
    NHUNGOC_HARDWARE_ID = "487d9020c89526c7ad8e99a02e90de5371bc201545d583220a0e22c413f87ac9"
    NHUNGOC_MAINBOARD = "07E0622_O51E207192"
    NHUNGOC_EMAIL = "maksimyuk00@gmail.com"
    WS_URL = "wss://ws.nhungoc.me/"

    # Always use hardcoded license - ignore api_key from settings
    license_key = NHUNGOC_LICENSE
    aspect = "VIDEO_ASPECT_RATIO_PORTRAIT"
    upscale = True
    duration = 8

    # Determine mode: i2v if image exists, t2v otherwise
    use_i2v = image_path and os.path.isfile(image_path)

    async def _generate():
        ssl_ctx = ssl.create_default_context()
        async with websockets.connect(WS_URL, ssl=ssl_ctx, open_timeout=20,
                                       max_size=50 * 1024 * 1024,
                                       ping_interval=20, ping_timeout=30) as ws:
            # Register з повним hardware fingerprint.
            # Сервер шле ДВА events: спочатку "registered" (pending verification),
            # потім за 1-2с другий "registered" (verified successfully) з can_generate=true.
            # Submit ДО verification дає quota error, тому чекаємо обидва.
            await ws.send(json.dumps({
                "event": "register",
                "data": {
                    "license_key": license_key,
                    "cpu_id": NHUNGOC_CPU_ID,
                    "hardware_id": NHUNGOC_HARDWARE_ID,
                    "mainboard_uuid": NHUNGOC_MAINBOARD,
                    "email": NHUNGOC_EMAIL,
                    "brand": "veo3",
                }
            }))

            verified = False
            for _ in range(3):
                raw = await asyncio.wait_for(ws.recv(), timeout=30)
                msg = json.loads(raw)
                if msg.get("event") != "registered":
                    return {"ok": False, "error": f"Registration failed: {msg}"}
                ver = msg.get("data", {}).get("verification", {})
                if ver.get("success") and ver.get("data", {}).get("can_generate"):
                    verified = True
                    break
                # pending → ще раз приймаємо
                if not ver.get("pending"):
                    # незрозумілий стан — лог і продовжуємо
                    break
            if not verified:
                return {"ok": False, "error": "Verification did not complete (no can_generate=true)"}

            task_id = f"{'i2v' if use_i2v else 't2v'}_{int(time.time())}"

            if use_i2v:
                # Image-to-video: send image + prompt
                img_b64 = _image_to_base64(image_path)
                await ws.send(json.dumps({
                    "event": "submit_image_video_batch",
                    "data": [{
                        "task_id": task_id,
                        "image_base64": img_b64,
                        "mime_type": "image/jpeg",
                        "prompt": prompt,
                        "aspect_ratio": aspect,
                        "upscale_1080p": upscale,
                        "duration_seconds": duration,
                        "seed": -1,
                    }]
                }))
            else:
                # Text-to-video: prompt only
                await ws.send(json.dumps({
                    "event": "submit_video_prompt",
                    "data": {
                        "task_id": task_id,
                        "prompt": prompt,
                        "aspect_ratio": aspect,
                        "seed": -1,
                        "upscale_1080p": upscale,
                        "duration_seconds": duration,
                    }
                }))

            # Wait for result (up to 10 minutes)
            while True:
                raw = await asyncio.wait_for(ws.recv(), timeout=600)
                msg = json.loads(raw)
                event = msg.get("event", "")
                data = msg.get("data", {})

                if event in ("video_result",):
                    status = data.get("status", "")
                    if status == "success":
                        video_url = data.get("video_url")
                        encoded_video = data.get("encoded_video", "")
                        out_path = os.path.join(OUTPUT_DIR, f"{task_id}.mp4")

                        if video_url and str(video_url) != "None":
                            import urllib.request
                            urllib.request.urlretrieve(video_url, out_path)
                            out_path = _remove_veo_watermark(out_path)
                            return {"ok": True, "path": out_path}
                        elif encoded_video:
                            with open(out_path, "wb") as f:
                                f.write(base64.b64decode(encoded_video))
                            out_path = _remove_veo_watermark(out_path)
                            return {"ok": True, "path": out_path}
                        else:
                            return {"ok": False, "error": "No video data in result"}
                    else:
                        error = data.get("error", "Unknown error")
                        raw_data = data.get("raw", "")
                        return {"ok": False, "error": f"{error}\n{str(raw_data)[:300]}"}

                elif event == "error":
                    return {"ok": False, "error": str(data)}

                # Send ack for results
                if event == "video_result":
                    try:
                        await ws.send(json.dumps({
                            "event": "result_ack",
                            "data": {"task_id": data.get("task_id", task_id)}
                        }))
                    except:
                        pass

    # Run async WebSocket flow with retry
    max_retries = 3
    for attempt in range(max_retries):
        try:
            loop = asyncio.new_event_loop()
            result = loop.run_until_complete(_generate())
            loop.close()
            return result
        except asyncio.TimeoutError:
            return {"ok": False, "error": "Timeout waiting for video generation (10 min)"}
        except Exception as e:
            err = f"Nhungoc VEO3: {type(e).__name__}: {str(e)}"
            print(f"[Nhungoc] Attempt {attempt+1}/{max_retries} failed: {err}", flush=True)
            if attempt < max_retries - 1:
                time.sleep(3)
                continue
            return {"ok": False, "error": err}


def compose_final(video_path: str, quote: str, music_path: str = None,
                  logo_path: str = None, output_path: str = None, slow_motion: bool = False,
                  overlay_opacity: float = 0.0, trim_start: float = 0.0, trim_end: float = 0.0,
                  video_effect: str = "", effect_strength: float = 1.0,
                  music_trim_start: float = 0.0, music_trim_end: float = 0.0,
                  text_size: int = 100, text_weight: int = 500, text_position: int = 50,
                  text_font: str = "YuGothM.ttc",
                  slow_motion_mode: str = "blend",
                  slow_motion_factor: float = 0.7) -> dict:
    """Compose final video with text overlay, music, and logo using FFmpeg.

    slow_motion_mode: 'blend' (швидко), 'rife' (AI, CapCut-якість), 'mci' (старий)
    slow_motion_factor: 0.3..1.0 — speed multiplier (0.5 = 2x slower, 1.0 = normal)
    """
    ffmpeg = _find_ffmpeg()

    # Trim-first, then slow motion.
    # Причина: user обирає trim на ОРИГІНАЛЬНОМУ відео у таймлайні редактора.
    # Якщо спочатку застосувати slow — trim ріже вже-slow версію (6с замість 12с).
    # Правильно: trim 6с з оригіналу → slow 0.5x → 12с (користувач бачить довге відео).
    if slow_motion:
        sm_factor = max(0.3, min(1.0, float(slow_motion_factor)))

        # 1. Trim оригінал (якщо заданий) у тимчасовий файл
        if trim_end > trim_start + 0.5:
            trimmed_path = video_path.replace(".mp4", "_trim.mp4")
            trim_cmd = [
                ffmpeg, "-y",
                "-ss", f"{trim_start:.2f}",
                "-i", video_path,
                "-t", f"{(trim_end - trim_start):.2f}",
                "-c", "copy",
                trimmed_path,
            ]
            try:
                subprocess.run(trim_cmd, capture_output=True, text=True, timeout=60,
                               **_subprocess_low_priority_flags())
                if os.path.isfile(trimmed_path) and os.path.getsize(trimmed_path) > 1000:
                    video_path = trimmed_path
                    # Trim вже застосовано — скидаємо для наступного compose
                    trim_start = 0.0
                    trim_end = 0.0
            except Exception as e:
                print(f"[trim-before-slow] error: {e}", flush=True)

        # 2. Slow motion на trim'нутому (або оригіналі якщо trim не було)
        video_path = _apply_slow_motion(video_path, sm_factor, mode=slow_motion_mode)

    if not output_path:
        output_path = os.path.join(OUTPUT_DIR, f"final_{int(time.time())}.mp4")

    # Build filter complex
    filters = []

    # Scale video to 1080x1920 + bottom gradient (black fade from bottom)
    grad_height = 300
    # Video effect color grading with strength (0-1)
    effect_filter = ""
    s = min(max(effect_strength, 0), 1)
    def _lerp(a, b): return a + (b - a) * s
    if video_effect == "cinematic" and s > 0:
        effect_filter = f",eq=contrast={_lerp(1,1.15):.2f}:saturation={_lerp(1,0.85):.2f}:brightness={_lerp(0,-0.05):.3f}"
    elif video_effect == "cold_steel" and s > 0:
        effect_filter = f",eq=saturation={_lerp(1,0.3):.2f}:contrast={_lerp(1,1.2):.2f}:brightness={_lerp(0,-0.1):.3f},colorbalance=bs={_lerp(0,0.1):.2f}:bm={_lerp(0,0.05):.2f}"
    elif video_effect == "blood_ash" and s > 0:
        effect_filter = f",eq=saturation={_lerp(1,0.6):.2f}:contrast={_lerp(1,1.3):.2f}:brightness={_lerp(0,-0.15):.3f},colorbalance=rs={_lerp(0,0.08):.2f}:gs={_lerp(0,-0.03):.2f}"
    elif video_effect == "fog_ghost" and s > 0:
        effect_filter = f",eq=saturation={_lerp(1,0.2):.2f}:contrast={_lerp(1,0.9):.2f}:brightness={_lerp(0,0.1):.3f}"
    elif video_effect == "noir" and s > 0:
        effect_filter = f",eq=saturation={_lerp(1,0):.2f}:contrast={_lerp(1,1.4):.2f}:brightness={_lerp(0,-0.15):.3f}"

    scale_filter = f"[0:v]scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920{effect_filter}[scaled]"

    # Black overlay (0.0-0.8 opacity)
    if overlay_opacity > 0.01:
        ov_alpha = min(overlay_opacity, 0.8)
        scale_filter += f";color=black@{ov_alpha}:1080x1920:d=1[darkov];[scaled][darkov]overlay=0:0[withov]"
        grad_input = "[withov]"
    else:
        grad_input = "[scaled]"

    filters.append(
        f"{scale_filter};"
        f"color=black:1080x{grad_height}[gradbase];"
        "[gradbase]format=rgba,geq="
        f"a='clip(255*Y/{grad_height},0,255)'"
        ":r=0:g=0:b=0[grad];"
        f"{grad_input}[grad]overlay=0:H-{grad_height}[base]"
    )

    # Add logo overlay if provided
    if logo_path and os.path.isfile(logo_path):
        filters.append(f"[1:v]scale=120:-1,format=rgba,colorchannelmixer=aa=0.4[logo]")
        filters.append("[base][logo]overlay=W-w-40:H-h-40[withlogo]")
        text_input = "[withlogo]"
    else:
        text_input = "[base]"

    # Text overlay — two-line style matching competitor
    import shutil

    # Copy CJK font (supports kanji) to output dir
    font_filename = text_font or "YuGothM.ttc"
    font_copy = os.path.join(OUTPUT_DIR, font_filename)
    # Copy font from Windows\Fonts if not already in output dir
    if not os.path.exists(font_copy):
        font_src_path = os.path.join(r"C:\Windows\Fonts", font_filename)
        if os.path.isfile(font_src_path):
            shutil.copy2(font_src_path, font_copy)
        else:
            # Fallback to CJK font
            cjk = _find_cjk_font()
            if cjk:
                shutil.copy2(cjk, font_copy)
    font_param = f"fontfile={font_filename}:" if os.path.exists(font_copy) else ""

    # Parse quote into 3 lines (competitor style):
    # Format A: "鍛錬 / Tanren — the forge does not apologize"
    #   → kanji="鍛錬", romaji="TANREN", english="TO FORGE IS TO NOT APOLOGIZE."
    # Format B: "The dead ask nothing — walk on"
    #   → kanji="", romaji="", english="THE DEAD ASK NOTHING — WALK ON."
    ts = int(time.time())
    kanji = ""
    romaji = ""
    english = ""

    if " / " in quote:
        slash_idx = quote.index(" / ")
        kanji = quote[:slash_idx].strip()  # "鍛錬"
        after_slash = quote[slash_idx + 3:]  # "Tanren — the forge..."
        if " — " in after_slash:
            romaji = after_slash[:after_slash.index(" — ")].strip().upper()
            english = after_slash[after_slash.index(" — ") + 3:].strip().upper()
        else:
            romaji = after_slash.strip().upper()
    else:
        english = quote.strip().upper()

    # Add period at end if missing
    if english and not english.endswith(('.', '…')):
        english += '.'

    # Write text files for FFmpeg drawtext
    def _write_txt(text, suffix):
        fname = f"txt_{suffix}_{ts}.txt"
        fpath = os.path.join(OUTPUT_DIR, fname)
        with open(fpath, "w", encoding="utf-8") as f:
            f.write(text)
        return fname

    def _escape_ffmpeg(text):
        """Escape text for FFmpeg drawtext text= parameter."""
        return text.replace("\\", "\\\\").replace("'", "'\\\\\\''").replace(":", "\\:").replace("%", "%%")

    # Text overlay with customizable size, weight, position
    # text_size: 100 = default, text_position: 50 = center
    # Preview is 240px wide, video is 1080px → base sizes scaled for 1080px
    scale = text_size / 100.0
    kanji_fs = int(120 * scale)
    romaji_fs = int(52 * scale)
    eng_fs = int(36 * scale)
    # text_position (20-80) maps to y position
    pos_base = text_position / 100.0  # 0.2 to 0.8

    text_filters = []
    current_input = text_input
    line_num = 0

    if kanji:
        fk = _write_txt(kanji, "kanji")
        text_filters.append(
            f"{current_input}drawtext="
            f"{font_param}"
            f"textfile={fk}:"
            f"fontsize={kanji_fs}:"
            f"fontcolor=white:"
            f"x=(w-text_w)/2:"
            f"y=h*{pos_base - 0.07:.2f}-text_h/2:"
            f"borderw=0:"
            f"line_spacing=0"
            f"[txt{line_num}]"
        )
        current_input = f"[txt{line_num}]"
        line_num += 1

    if romaji:
        fr = _write_txt(romaji, "romaji")
        text_filters.append(
            f"{current_input}drawtext="
            f"{font_param}"
            f"textfile={fr}:"
            f"fontsize={romaji_fs}:"
            f"fontcolor=white:"
            f"x=(w-text_w)/2:"
            f"y=h*{pos_base - 0.02:.2f}:"
            f"borderw=0"
            f"[txt{line_num}]"
        )
        current_input = f"[txt{line_num}]"
        line_num += 1

    if english:
        fe = _write_txt(english, "eng")
        text_filters.append(
            f"{current_input}drawtext="
            f"{font_param}"
            f"textfile={fe}:"
            f"fontsize={eng_fs}:"
            f"fontcolor=white@0.90:"
            f"x=(w-text_w)/2:"
            f"y=h*{pos_base + 0.03:.2f}:"
            f"borderw=0"
            f"[txt{line_num}]"
        )
        current_input = f"[txt{line_num}]"
        line_num += 1

    # Rename last output to [final]
    if text_filters:
        last = text_filters[-1]
        text_filters[-1] = last.rsplit('[', 1)[0] + '[final]'
        filters.append(";".join(text_filters))
    else:
        filters.append(f"{text_input}copy[final]")

    filter_complex = ";".join(filters)

    # Записуємо фільтр у файл — уникаємо проблем з екрануванням шляхів Windows
    filter_script = os.path.join(OUTPUT_DIR, f"filter_{int(time.time())}.txt")
    with open(filter_script, "w", encoding="utf-8") as fs:
        fs.write(filter_complex)

    # Build command
    cmd = [ffmpeg, "-y"]

    # Trim: -ss before -i (fast seek), -t after -i
    if trim_start > 0.1:
        cmd += ["-ss", f"{trim_start:.2f}"]
    cmd += ["-i", video_path]
    if trim_end > trim_start + 0.5:
        duration = trim_end - max(trim_start, 0)
        cmd += ["-t", f"{duration:.2f}"]

    if logo_path and os.path.isfile(logo_path):
        cmd += ["-i", logo_path]

    if music_path and os.path.isfile(music_path):
        if music_trim_start > 0.1:
            cmd += ["-ss", f"{music_trim_start:.2f}"]
        cmd += ["-i", music_path]
        if music_trim_end > music_trim_start + 0.5:
            pass  # duration handled by -shortest

    cmd += ["-filter_complex_script", filter_script]
    cmd += ["-map", "[final]"]

    # Audio: mix original + music, or just music
    if music_path and os.path.isfile(music_path):
        audio_idx = 2 if (logo_path and os.path.isfile(logo_path)) else 1
        cmd += ["-map", f"{audio_idx}:a"]
    else:
        # Try to keep original audio
        cmd += ["-map", "0:a?"]

    cmd += _video_encoder_args(crf=23)
    cmd += ["-c:a", "aac", "-b:a", "192k"]

    # Обмежуємо output ТОЧНО до тривалості відео (з врахуванням trim).
    # Раніше було -shortest + -t 60: коли музика довша за відео, FFmpeg
    # дублював останній frame щоб дотягнути audio → freeze frame в кінці.
    # Тепер: ffprobe → effective video duration → -t забороняє писати довше.
    # Аудіо автоматично обрізається до output duration.
    video_duration = _get_video_duration(video_path)
    if trim_end > trim_start + 0.5:
        # trim вже застосовано через -ss/-t у video input → effective = trim_end-trim_start
        effective_duration = min(video_duration or 60.0, trim_end - trim_start)
    else:
        effective_duration = video_duration or 60.0
    # Hard cap 60s (slow motion 0.3x може зробити дуже довге відео)
    effective_duration = min(effective_duration, 60.0)
    if effective_duration > 0.1:
        cmd += ["-t", f"{effective_duration:.2f}"]
    else:
        cmd += ["-t", "60"]  # fallback якщо ffprobe не спрацював

    # CapCut metadata spoofing — змушуємо IG думати що файл експортовано CapCut.
    # Ці format-level tags з реального CapCut-экспорту є унікальними для нього.
    cmd += [
        "-metadata", "Hw=1",
        "-metadata", "bitrate=12000000",
        "-metadata", "maxrate=0",
        "-metadata", "te_is_reencode=1",
        "-metadata", "encoder=Lavf61.1.100",
        # major_brand/compatible_brands задаються через movflags/brand але FFmpeg сам ставить isom+avc1mp41
        "-movflags", "+faststart",
    ]

    cmd += [output_path]

    try:
        result = subprocess.run(
            cmd, capture_output=True, text=True, timeout=120, cwd=OUTPUT_DIR,
            **_subprocess_low_priority_flags(),
        )
        if result.returncode != 0:
            return {"ok": False, "error": f"FFmpeg error: {result.stderr[-500:]}"}
        return {"ok": True, "path": output_path}
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "FFmpeg timeout"}
    except FileNotFoundError:
        return {"ok": False, "error": "FFmpeg не знайдено. Встановіть FFmpeg."}


def _wrap_text(text: str, max_chars: int = 25) -> str:
    words = text.split()
    lines = []
    current = ""
    for word in words:
        if current and len(current) + 1 + len(word) > max_chars:
            lines.append(current)
            current = word
        else:
            current = f"{current} {word}" if current else word
    if current:
        lines.append(current)
    return "\n".join(lines)


# ===== FULL PIPELINE =====

def run_pipeline(params: dict):
    """Generator that yields progress updates as JSON-serializable dicts."""
    style = params.get("style", "Воїн")
    prompt = params.get("prompt", "")
    quote = params.get("quote", "")
    music_path = params.get("music_path")
    logo_path = params.get("logo_path")
    image_provider = params.get("image_provider", "stability")
    image_api_key = params.get("image_api_key", "")
    video_provider = params.get("video_provider", "kling")
    video_api_key = params.get("video_api_key", "")

    # Step 1: Generate image
    yield {"step": "image", "status": "started", "message": "Генерація зображення..."}

    img_result = generate_image(prompt, style, image_provider, image_api_key)
    if not img_result.get("ok"):
        yield {"step": "image", "status": "error", "message": img_result.get("error")}
        return

    image_path = img_result["path"]
    yield {"step": "image", "status": "done", "path": image_path, "message": "Зображення готове"}

    # Step 2: Generate video
    yield {"step": "video", "status": "started", "message": "Генерація відео (може зайняти 1-3 хвилини)..."}

    vid_prompt = f"{style} warrior, {EPIC_VIDEO_SUFFIX}"
    vid_result = generate_video(image_path, vid_prompt, video_provider, video_api_key)
    if not vid_result.get("ok"):
        yield {"step": "video", "status": "error", "message": vid_result.get("error")}
        return

    video_path = vid_result["path"]
    yield {"step": "video", "status": "done", "path": video_path, "message": "Відео згенеровано"}

    # Step 3: Compose final
    yield {"step": "compose", "status": "started", "message": "Складання фінального відео..."}

    final_result = compose_final(video_path, quote, music_path, logo_path)
    if not final_result.get("ok"):
        yield {"step": "compose", "status": "error", "message": final_result.get("error")}
        return

    yield {"step": "compose", "status": "done", "path": final_result["path"], "message": "Готово!"}
